import sys; sys.path.insert(0,'/tmp/probe')
import png
from ft import load, render_char

def ditaa_bitmap(path):
    w,h,ch,ct,px,chunks = png.load(path)
    pts={}; minx,miny=w,h; maxx=maxy=-1
    for y in range(h):
        for x in range(w):
            p=px[(y*w+x)*ch:(y*w+x)*ch+3]
            if p[:3]!=b'\xff\xff\xff':
                pts[(x,y)]=255-sum(p[:3])//3
                minx=min(minx,x);maxx=max(maxx,x);miny=min(miny,y);maxy=max(maxy,y)
    W=maxx-minx+1; H=maxy-miny+1
    bm=[[0]*W for _ in range(H)]
    for (x,y),v in pts.items(): bm[y-miny][x-minx]=v
    return bm

def ft_bitmap(face,ch,flags):
    r=render_char(face,ch,flags,0)
    if r is None or r['rows']==0: return [[0]]
    p=abs(r['pitch'])
    return [[r['data'][y*p+x] for x in range(r['w'])] for y in range(r['rows'])]

def bestdiff(b1,b2,maxs=4):
    best=None
    for dy in range(-maxs,maxs+1):
        for dx in range(-maxs,maxs+1):
            d=0
            ys=range(min(0,dy),max(len(b1),len(b2)+dy))
            xs=range(min(0,dx),max(len(b1[0]),len(b2[0])+dx))
            for y in ys:
                for x in xs:
                    a=b1[y][x] if 0<=y<len(b1) and 0<=x<len(b1[0]) else 0
                    b=b2[y-dy][x-dx] if 0<=y-dy<len(b2) and 0<=x-dx<len(b2[0]) else 0
                    d+=abs(a-b)
            if best is None or d<best[0]: best=(d,dx,dy)
    return best

chars="AHiBWgjme0@Sxo"
fp="/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"
for size in [14,15,16]:
    face=load(fp,size,0)
    tot=0
    for c in chars:
        b1=ditaa_bitmap(f"ch_{c}.png")
        b2=ft_bitmap(face,c,0)
        d,dx,dy=bestdiff(b1,b2)
        tot+=d
        if size==15: print(c,"diff",d,"shift",dx,dy,"ditaa",len(b1[0]),len(b1),"ft",len(b2[0]),len(b2))
    print("size",size,"TOTAL",tot)
EOF
